from __future__ import annotations

from datetime import datetime, timedelta
from typing import Optional, Union, Unpack, TypedDict

from ..base.client import BaseClient
from ...client.decorators import api_version_check


class TasksKwargs(TypedDict):
    cursor: str


class TasksMethods(BaseClient):
    """
    Методы группы 'Задачи' из https://im-docs.corp.mail.ru/
    """

    async def tasks_add(
        self,
        title: str,
        endTime: int,
        assignee: str,
        label: str,
        priority: str,
        tags: list[str],
    ) -> dict:
        """
        Метод для создания новой задачи пользователем.
        """
        return await self.post(
            "tasks/add",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "title": title,
                    "endTime": int(endTime),
                    "assignee": assignee,
                    "label": label,
                    "priority": priority,
                    "tags": tags,
                },
            },
        )

    async def tasks_edit(self, taskId: str, **kwargs) -> dict:
        """
        Метод для редактирования задачи пользователем.
        """
        return await self.post(
            "tasks/edit",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"taskId": taskId, **kwargs},
            },
        )

    async def tasks_list(
        self,
        _filter: str,
        pageSize: int = 10,
        **kwargs: Unpack[TasksKwargs],
    ) -> dict:
        """
        Метод для получения список задач, на которые подписан пользователь.

        :param _filter: ID пользовательского фильтра из /tasks/filters/list.
        Позволяет ограничить выдачу задач
        :param cursor: Курсор, полученный в ответе на предыдущий запрос.
        :param pageSize: Ожидаемое количество результатов в одном ответе.
        :return: тело ответа сервера
        """
        return await self.post(
            "tasks/list",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "filter": _filter,
                    **kwargs,
                    "pageSize": pageSize,
                },
            },
        )

    async def tasks_filters_list(self):
        """
        Получение списка фильтров в табе задач
        """
        return await self.post(
            "tasks/filters/list",
            json={"reqId": self.getReqId(), "aimsid": self.aimsid},
        )

    async def tasks_filters_add(
        self,
        name: str,
        creators: [tuple[str, ...], list[str]] = (),
        assignees: [tuple[str, ...], list[str]] = (),
        statuses: [tuple[str, ...], list[str]] = (),
        deadline: Optional[str | datetime] = None,
        subscribed: bool = False,
        withChanges: bool = False,
    ):
        """
        Метод для создания нового фильтра пользователем.
        """
        if isinstance(deadline, str):
            deadline = {"type": "predefined", "predefined": deadline}
        elif deadline is None:
            deadline = None
        elif isinstance(deadline, dict):
            deadline = deadline
        else:
            deadline = {"type": "date", "date": int(deadline.timestamp())}

        return await self.post(
            "tasks/filters/add",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "name": name,
                    "assignees": assignees,
                    "creators": creators,
                    "statuses": statuses,
                    "deadline": deadline,
                    "subscribed": subscribed,
                    "withChanges": withChanges,
                },
            },
        )

    async def tasks_filters_edit(
        self,
        filter_id: str,
        name: Optional[str] = None,
        assignees: [tuple[str, ...], list[str]] = (),
        statuses: [tuple[str, ...], list[str]] = (),
        deadline: Optional[str | datetime] = None,
        subscribed: bool = False,
        withChanges: bool = False,
    ):
        """
        Метод для изменения фильтра пользователем.
        """
        if deadline is None:
            deadline = datetime.now() + timedelta(days=5)

        if filter_id == "c55aef38-7e17-406e-8160-3834f9ff92c3":
            raise ValueError("Cannot delete filter 'All'")
        return await self.post(
            "tasks/filters/edit",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "id": filter_id,
                    "name": name,
                    "assignees": assignees,
                    "creators": [self.uin],
                    "statuses": statuses,
                    "deadline": {"type": "predefined", "predefined": deadline}
                    if isinstance(deadline, str)
                    else {"type": "date", "date": int(deadline.timestamp())},
                    "subscribed": subscribed,
                    "withChanges": withChanges,
                },
            },
        )

    async def tasks_filters_delete(self, filter_id: str):
        """
        Метод для удаления фильтра пользователем.
        """
        if filter_id == "c55aef38-7e17-406e-8160-3834f9ff92c3":
            raise ValueError("Cannot delete filter 'All'")
        return await self.post(
            "tasks/filters/delete",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"id": filter_id},
            },
        )

    async def task_filters_reorder(self, filter_id: str, order: int):
        """
        Метод для изменения порядка фильтров пользователем.
        """
        return await self.post(
            "tasks/filters/reorder",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"filters": [{"id": filter_id, "order": order}]},
            },
        )

    async def task_filters_reorder_full(self, filters: list[dict[str, str | int]]):
        """
        Метод для изменения порядка фильтров пользователем.
        """
        return await self.post(
            "tasks/filters/reorder",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"filters": filters},
            },
        )

    async def tasks_setRead(self, tasks: Union[list[str], tuple[str]]):
        """
        Метод для установки флага прочитанности списка задач.
        """
        return await self.post(
            "tasks/setRead",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"tasks": tasks},
            },
        )

    async def tasks_getUserTags(
        self,
        filter_id: Optional[str] = None,
        cursor: Optional[str] = None,
        page_size: int = 10,
    ):
        """
        Метод для получения списка тегов задач,
        на которые подписан пользователь,
        отсортированный по частоте использования.
        """
        if filter_id is None:
            return await self.post(
                "rapi/tasks/getUserTags",
                json={
                    "reqId": self.getReqId(),
                    "aimsid": self.aimsid,
                    "params": {
                        "pageSize": page_size,
                    },
                },
            )
        return await self.post(
            "tasks/getUserTags",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "filter_id": filter_id,
                    "pageSize": page_size,
                },
            },
        )

    async def tasks_notifications_list(self, task_id: str):
        """
        Метод для получения напоминаний для задачи.
        """
        return await self.post(
            "tasks/notifications/list",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"taskId": task_id},
            },
        )

    async def tasks_notifications_custom_add(self, task_id: str, timestamp: int):
        """
        Метод для добавления кастомного напоминания.
        """
        return await self.post(
            "tasks/notifications/custom/add",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"taskId": task_id, "time": timestamp},
            },
        )

    async def tasks_notifications_custom_delete(self, task_id: str, timestamp: int):
        """
        Метод для удаления кастомного напоминания.
        """
        return await self.post(
            "tasks/notifications/custom/delete",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"taskId": task_id, "time": timestamp},
            },
        )

    async def tasks_notifications_default_update(
        self,
        task_id: str,
        defaultNotifications: list[dict[str, Union[bool, int]]],
    ):
        """
        Метод для обновления стандартных напоминаний.
        """
        return await self.post(
            "tasks/notifications/default/update",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "taskId": task_id,
                    "defaultNotifications": defaultNotifications,
                },
            },
        )

    @api_version_check(min_version=119)
    async def tasks_add_subscriber(self, task_id: str, user: str):
        """
        Метод добавляет пользователя как подписчика/наблюдателя в задачу.
        После чего, ему предоставляется доступ к обсуждениям.
        Должно вызываться от имени пользователя, являющегося участником задачи.
        """
        return await self.post(
            "tasks/addSubscriber",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"taskId": task_id, "user": user},
            },
        )

    @api_version_check(min_version=119)
    async def tasks_del_subscriber(self, task_id: str, user: str):
        """
        Метод удаляет пользователя как подписчика/наблюдателя из задачи.
        Должно вызываться от имени пользователя, являющегося участником задачи.
        """
        return await self.post(
            "tasks/delSubscriber",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"taskId": task_id, "user": user},
            },
        )
